fn sqlite_snapshot_semio_graph_controlled_native_output(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let mut snapshot=fixture();snapshot.nodes[0].label="x".repeat(f["nativeOutputBytes"].as_u64().unwrap() as usize);
