fn sqlite_snapshot_semio_graph_independent_join_query_and_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(db.query('SELECT kind FROM semio_graph_port ORDER BY ordinal').all().map(r=>r.kind).join(',')!=='in,out,in_out')throw Error('ports');if(db.query('SELECT source_node_id,target_node_id FROM semio_graph_edge WHERE native_id=\"self\"').get().source_node_id!==1)throw Error('self edge');db.query(\"UPDATE semio_graph_value SET string_value='independently edited' WHERE kind='str'\").run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let restored=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let mut expected=fixture();if let SemioValue::Map{entries}=&mut expected.nodes[0].properties[0].value{if let SemioValue::List{items}=&mut entries[0].value{items[0]=SemioValue::Str{value:"independently edited".into()};}}assert_eq!(restored,expected);}

